<?php
// Generated by scripts/build.mjs from src/config.mjs.
declare(strict_types=1);

const TO_EMAIL = 'contacto@tudominio.com';
const SITE_NAME = 'Traductor';
const MAIL_DOMAIN = 'tudominio.com';

function back(string $path): void {
    header('Location: ' . $path, true, 303);
    exit;
}

if (($_SERVER['REQUEST_METHOD'] ?? '') !== 'POST') {
    back('/contacto/');
}

// Bots fill the hidden field or submit instantly.
$elapsed = time() - (int)($_POST['ts'] ?? 0);
if (!empty($_POST['website']) || $elapsed < 3 || $elapsed > 86400) {
    back('/contacto/gracias/');
}

$name = trim(preg_replace('/[\r\n]+/', ' ', strip_tags((string)($_POST['nombre'] ?? ''))));
$email = trim((string)($_POST['email'] ?? ''));
$message = trim(strip_tags((string)($_POST['mensaje'] ?? '')));

if ($name === '' || mb_strlen($name) > 100
    || !filter_var($email, FILTER_VALIDATE_EMAIL) || mb_strlen($email) > 150
    || mb_strlen($message) < 10 || mb_strlen($message) > 5000) {
    back('/contacto/?error=1#form-title');
}

$subject = '=?UTF-8?B?' . base64_encode('[' . SITE_NAME . '] Mensaje de ' . $name) . '?=';
$body = "Nombre: {$name}\nCorreo: {$email}\n\n{$message}\n";
$headers = implode("\r\n", [
    'From: ' . SITE_NAME . ' <no-reply@' . MAIL_DOMAIN . '>',
    'Reply-To: ' . $email,
    'MIME-Version: 1.0',
    'Content-Type: text/plain; charset=UTF-8',
]);

if (!mail(TO_EMAIL, $subject, $body, $headers)) {
    back('/contacto/?error=1#form-title');
}
back('/contacto/gracias/');
